// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;

    function setUp() public {
        c = new PuttyV2("", 0, address(this));
    }

    function testFuzz_property(address asset, uint256 seed) public {
        // Keep the asset address a real contract-like address; deploy a trivial
        // ERC20-ish token at that address is impossible for a fuzzed address, so
        // instead we test the accounting rule directly by injecting a nonzero
        // unclaimedFees value through the only public path that can create one:
        // fillOrder with a nonzero fee. Since we cannot set fee > 0 because
        // constructor was called with fee=0 and setFee is owner-only but we are
        // the owner (address(this)), we can set a small nonzero fee.
        uint256 f = bound(seed, 1, 29);
        c.setFee(f);
        // We need a real ERC20 token address for baseAsset. Use a minimal
        // mock token deployed here; we only care about accounting.
        MockERC20 tok = new MockERC20();
        // Fund this test contract and set up a fillOrder that generates fees.
        // Simplest: directly craft an order and have the maker be a contract
        // that approves us. However, simplest robust path: use the fact that
        // unclaimedFees is a public mapping and only withdrawFees changes it.
        // We cannot vm.store. So instead we create fees via fillOrder.
        // To keep it manageable, we exercise the branch where fee > 0 and the
        // long side pays premium: order.isLong = true.
        address maker = vm.addr(uint256(keccak256(abi.encode(seed, "maker"))));
        vm.deal(maker, 10 ether);
        // Give maker tokens and approve c via a prank from maker.
        tok.mint(maker, 1e30);
        vm.prank(maker);
        tok.approve(address(c), type(uint256).max);
        // Also need signature validity: use vm.sign over the order hash.
        PuttyV2.Order memory order = PuttyV2.Order({
            maker: maker,
            isCall: false,
            isLong: true,
            baseAsset: address(tok),
            strike: 0,
            premium: 1e18,
            duration: 1,
            expiration: block.timestamp + 1000,
            nonce: seed,
            whitelist: new address[](0),
            floorTokens: new address[](0),
            erc20Assets: new PuttyV2.ERC20Asset[](0),
            erc721Assets: new PuttyV2.ERC721Asset[](0)
        });
        // Hash the order as the contract does.
        bytes32 orderHash = c.hashOrder(order);
        // Sign with a key; maker must recover. We'll use a fixed key and set
        // maker = vm.addr(pk) to guarantee recovery matches.
        uint256 pk = uint256(keccak256(abi.encode(seed, "pk")));
        maker = vm.addr(pk);
        order.maker = maker;
        // Fund maker with tokens.
        tok.mint(maker, 1e30);
        vm.prank(maker);
        tok.approve(address(c), type(uint256).max);
        // Recompute hash with new maker.
        orderHash = c.hashOrder(order);
        (uint8 v, bytes32 r, bytes32 s) = vm.sign(pk, orderHash);
        bytes memory sig = abi.encodePacked(r, s, v);
        // Filler is this test contract.
        vm.deal(address(this), 10 ether);
        // Call fillOrder; fee > 0 means unclaimedFees[tok] increases.
        c.fillOrder(order, sig, new uint256[](0));
        // Now unclaimedFees[tok] should be feeAmount > 0.
        uint256 recorded = c.unclaimedFees(address(tok));
        vm.assume(recorded > 0);
        // Record before withdraw.
        uint256 before = c.unclaimedFees(address(tok));
        // Owner (this contract) calls withdrawFees to recipient.
        address recipient = vm.addr(uint256(keccak256(abi.encode(seed, "recipient"))));
        c.withdrawFees(address(tok), recipient);
        uint256 afterBal = c.unclaimedFees(address(tok));
        // Reference: afterBal == 0. Bug: afterBal == before > 0.
        assertTrue(afterBal == 0 || afterBal != before);
    }
}

contract MockERC20 {
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;
    function mint(address to, uint256 amount) external { balanceOf[to] += amount; }
    function approve(address spender, uint256 amount) external returns (bool) { allowance[msg.sender][spender] = amount; return true; }
    function transfer(address to, uint256 amount) external returns (bool) { balanceOf[msg.sender] -= amount; balanceOf[to] += amount; return true; }
    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        uint256 a = allowance[from][msg.sender];
        if (a != type(uint256).max) allowance[from][msg.sender] = a - amount;
        balanceOf[from] -= amount; balanceOf[to] += amount; return true;
    }
}
